### doc.go
// Package sessionparser reads pi session files (JSONL) written by pi with the pi-agent
// extensions.
//
// A session file has one JSON object per line. The first line is the [Header]; every other
// line is an entry that pi links into a tree by id and parentId. [Session.Branch] is the
// current branch: from the root to the last entry in the file. Two versions describe a file:
//
//   - [Header.Version] is pi's session format. pi owns it and migrates older files when it
//     loads them; this package reads format [SupportedFormatVersion] only.
//   - [Metadata.AgentVersion] is the pi-agent release that wrote the file, from its
//     "pi-agent.session-version" custom entries.
//
// [Parse] reads every entry's envelope and keeps the whole line in [Entry.Raw]. The data is
// read in groups, each on its own:
//
//   - [Session.Metadata]: header fields, pi-agent version, tags, name, models, errors.
//   - [Session.ToolCalls]: tool calls with their results and tool-ref handles.
//   - [Session.Metrics]: the pi-agent.metrics totals and samples.
//   - [Session.Subagents]: subagents started and their results.
//
// Values a file doesn't have are nil. Parsing is strict: an invalid line fails [Parse] with a
// [*LineError], and an invalid entry fails its group with an [*EntryError] (or an
// [*UnsupportedVersionError] for a pi-agent payload version this package doesn't know).
package sessionparser

### entry.go
package sessionparser

import (
	"bytes"
	"encoding/json"
	"fmt"
)

// pi's entry types.
const (
	// TypeSession is the header's type.
	TypeSession = "session"
	// TypeMessage is a conversation message (user, assistant, tool result, ...).
	TypeMessage = "message"
	// TypeModelChange records a switch of model.
	TypeModelChange = "model_change"
	// TypeSessionInfo holds the session's display name.
	TypeSessionInfo = "session_info"
	// TypeCustom is an extension's entry, never model context; its payload is "data".
	TypeCustom = "custom"
	// TypeCustomMessage is an extension's message, sent to the model; its payload is "details".
	TypeCustomMessage = "custom_message"
)

// pi-agent's custom types (src/shared/protocol.ts, src/subagent/protocol.ts).
const (
	// CustomTypeSessionVersion: the pi-agent release that wrote the entries after it.
	CustomTypeSessionVersion = "pi-agent.session-version"
	// CustomTypeTags: the session's tags; the last one in the file wins.
	CustomTypeTags = "pi-agent.tags"
	// CustomTypeError: an extension could not run and pi shut down.
	CustomTypeError = "pi-agent.error"
	// CustomTypeMetrics: session metrics, cumulative along the branch.
	CustomTypeMetrics = "pi-agent.metrics"
	// CustomTypeSubagentStart: a subagent was started.
	CustomTypeSubagentStart = "subagent-start"
	// CustomTypeSubagentEnd: a subagent result recorded at session end, not yet delivered.
	CustomTypeSubagentEnd = "subagent-end"
	// CustomTypeSubagentResult: a subagent result delivered to the model (custom_message).
	CustomTypeSubagentResult = "subagent-result"
)

// EntryError is an entry whose content is invalid for its type.
type EntryError struct {
	ID         string
	Type       string
	CustomType string
	Err        error
}

func (e *EntryError) Error() string {
	kind := e.Type
	if e.CustomType != "" {
		kind += " " + e.CustomType
	}
	return fmt.Sprintf("entry %q (%s): %v", e.ID, kind, e.Err)
}

func (e *EntryError) Unwrap() error { return e.Err }

// UnsupportedVersionError is a pi-agent entry whose payload version this package does not read.
type UnsupportedVersionError struct {
	CustomType string
	Version    int
	Supported  int
}

func (e *UnsupportedVersionError) Error() string {
	return fmt.Sprintf("%s version %d is not supported (want %d)", e.CustomType, e.Version, e.Supported)
}

func (e Entry) isCustom(customType string) bool {
	return e.Type == TypeCustom && e.CustomType == customType
}

func (e Entry) isCustomMessage(customType string) bool {
	return e.Type == TypeCustomMessage && e.CustomType == customType
}

// invalid wraps err as an [*EntryError] of e.
func (e Entry) invalid(err error) error {
	return &EntryError{ID: e.ID, Type: e.Type, CustomType: e.CustomType, Err: err}
}

// decodeField decodes the entry's top-level field name into v; missing or null is an error.
func (e Entry) decodeField(name string, v any) error {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(e.Raw, &fields); err != nil {
		return err
	}
	raw, ok := fields[name]
	if !ok || bytes.Equal(raw, []byte("null")) {
		return missing(name)
	}
	if err := json.Unmarshal(raw, v); err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	return nil
}

func missing(field string) error { return fmt.Errorf("missing %s", field) }

// checkVersion checks a versioned pi-agent payload.
func checkVersion(customType string, version *int, supported int) error {
	if version == nil {
		return missing("version")
	}
	if *version != supported {
		return &UnsupportedVersionError{CustomType: customType, Version: *version, Supported: supported}
	}
	return nil
}

### metadata.go
package sessionparser

import (
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

// TagsVersion is the pi-agent.tags payload version this package reads.
const TagsVersion = 1

// Metadata describes a session. Pointers and slices are nil when the file has no such entry.
type Metadata struct {
	SessionID string
	CWD       string
	StartedAt time.Time
	// FormatVersion is pi's session format (header "version").
	FormatVersion int
	// ParentSession is the session file this one was forked from.
	ParentSession *string

	// AgentVersion is the pi-agent release of the last pi-agent.session-version entry in the
	// file; nil for files written by pi-agent 0.11.0 or older, or without pi-agent.
	AgentVersion *string
	// Tags is the last pi-agent.tags entry in the file (tags belong to the whole file).
	Tags *Tags
	// Name is the session name of the last session_info entry in the file; nil when unnamed.
	Name *string

	// Models are the model changes on the current branch, in order.
	Models []ModelChange
	// Errors are the pi-agent.error entries on the current branch, in order.
	Errors []AgentError
}

// Tags is a pi-agent.tags entry: the session's whole tag list.
type Tags struct {
	// Tags in the order given; empty when cleared.
	Tags []string
	// Source is what set them: "flag" (--tags or task.json), "command" (/tags) or "default" (the
	// last segment of the cwd, for a session never tagged).
	Source string
	At     time.Time
}

// ModelChange is a model_change entry.
type ModelChange struct {
	Provider string
	ModelID  string
	At       time.Time
}

// AgentError is a pi-agent.error entry: an extension could not run.
type AgentError struct {
	Message string
	At      time.Time
}

// Metadata reads the session's metadata. Version, tags and name are per file, as their
// extensions define them; models and errors come from the current branch. An invalid entry
// of these types is an [*EntryError].
func (s *Session) Metadata() (*Metadata, error) {
	m := &Metadata{
		SessionID:     s.Header.ID,
		CWD:           s.Header.CWD,
		StartedAt:     s.Header.Timestamp,
		FormatVersion: s.Header.FormatVersion(),
	}
	if s.Header.ParentSession != "" {
		m.ParentSession = new(s.Header.ParentSession)
	}
	for _, e := range s.Entries {
		var err error
		switch {
		case e.isCustom(CustomTypeSessionVersion):
			err = m.readAgentVersion(e)
		case e.isCustom(CustomTypeTags):
			err = m.readTags(e)
		case e.Type == TypeSessionInfo:
			err = m.readName(e)
		}
		if err != nil {
			return nil, e.invalid(err)
		}
	}
	for _, e := range s.Branch() {
		var err error
		switch {
		case e.Type == TypeModelChange:
			err = m.readModel(e)
		case e.isCustom(CustomTypeError):
			err = m.readError(e)
		}
		if err != nil {
			return nil, e.invalid(err)
		}
	}
	return m, nil
}

func (m *Metadata) readAgentVersion(e Entry) error {
	var d struct {
		Version *string `json:"version"`
	}
	if err := e.decodeField("data", &d); err != nil {
		return err
	}
	if d.Version == nil || *d.Version == "" {
		return missing("data.version")
	}
	m.AgentVersion = d.Version
	return nil
}

func (m *Metadata) readTags(e Entry) error {
	var d struct {
		Version *int     `json:"version"`
		Tags    []string `json:"tags"`
		Source  string   `json:"source"`
	}
	if err := e.decodeField("data", &d); err != nil {
		return err
	}
	if err := checkVersion(CustomTypeTags, d.Version, TagsVersion); err != nil {
		return err
	}
	if d.Tags == nil {
		return missing("data.tags")
	}
	switch d.Source {
	case "flag", "command", "default":
	default:
		return fmt.Errorf("data.source %q is not flag, command or default", d.Source)
	}
	m.Tags = &Tags{Tags: d.Tags, Source: d.Source, At: e.Timestamp}
	return nil
}

func (m *Metadata) readName(e Entry) error {
	var d struct {
		Name *string `json:"name"`
	}
	if err := json.Unmarshal(e.Raw, &d); err != nil {
		return err
	}
	m.Name = nil
	if d.Name != nil && *d.Name != "" {
		m.Name = d.Name
	}
	return nil
}

func (m *Metadata) readModel(e Entry) error {
	var d struct {
		Provider string `json:"provider"`
		ModelID  string `json:"modelId"`
	}
	if err := json.Unmarshal(e.Raw, &d); err != nil {
		return err
	}
	if d.Provider == "" || d.ModelID == "" {
		return errors.New("missing provider or modelId")
	}
	m.Models = append(m.Models, ModelChange{Provider: d.Provider, ModelID: d.ModelID, At: e.Timestamp})
	return nil
}

func (m *Metadata) readError(e Entry) error {
	var d struct {
		Message *string `json:"message"`
	}
	if err := e.decodeField("data", &d); err != nil {
		return err
	}
	if d.Message == nil {
		return missing("data.message")
	}
	m.Errors = append(m.Errors, AgentError{Message: *d.Message, At: e.Timestamp})
	return nil
}

